create table if not exists public.ef_vocab_decks (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, name text not null, unique(user_id,name));
create table if not exists public.ef_vocab_cards (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, term text not null, definition text not null, translation text not null default '', collocations text not null default '', example text not null default '', source text not null default '', deck text not null default 'Personal vocabulary', due_at timestamptz not null default now(), interval_days numeric not null default 0, reviews integer not null default 0, unique(user_id,term));
create table if not exists public.ef_vocab_reviews (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, card_id uuid not null references public.ef_vocab_cards(id) on delete cascade, rating text not null check(rating in ('Again','Hard','Good','Easy')), reviewed_at timestamptz not null default now());
alter table public.ef_vocab_decks enable row level security;
alter table public.ef_vocab_cards enable row level security;
alter table public.ef_vocab_reviews enable row level security;
do $$ declare t text; begin foreach t in array array['ef_vocab_decks','ef_vocab_cards','ef_vocab_reviews'] loop execute format('drop policy if exists own_vocab on public.%I',t); execute format('create policy own_vocab on public.%I for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid())',t); execute format('grant select, insert, update, delete on public.%I to authenticated',t); end loop; end $$;
